#include <stddef.h>
#define VTOR_ALIGNMENT 0x100u

typedef struct {
    unsigned int ram_start;
    unsigned int ram_end;
    unsigned int code_start;
    unsigned int code_end;
} MemLayout;

static int in_range(unsigned int value, unsigned int start, unsigned int end)
{
    return (value >= start) && (value <= end);
}

int check_vector_table(const unsigned int *table, unsigned int table_addr,
                       const MemLayout *layout)
{
    if (table == NULL || layout == NULL) {
        return -1;
    }

    if ((table_addr & (VTOR_ALIGNMENT - 1u)) != 0u) {
        return 1;
    }

    if (table[0] == 0u || !in_range(table[0], layout->ram_start, layout->ram_end)) {
        return 2;
    }

    if (table[1] == 0u || !in_range(table[1], layout->code_start, layout->code_end)) {
        return 3;
    }

    return 0;
}
